# ==============================================================================
# Script de Atualizacao Automatica - Assistente de Campo (field-assistant)
# 100% ASCII / Base64 seguro para Windows PowerShell 5.1 e PowerShell 7
# ==============================================================================

$ErrorActionPreference = "Stop"
Write-Host "Restaurando arquivos originais compativeis do repositorio..." -ForegroundColor Cyan
git checkout e2caf14 -- lib/ui/widgets/map_location_picker_dialog.dart lib/ui/screens/connected_calendars_screen.dart lib/ui/screens/contacts_map_screen.dart

Write-Host "Aplicando atualizacoes nos arquivos do projeto..." -ForegroundColor Cyan

function Write-Base64File($relPath, $b64) {
    $fullPath = Join-Path $PWD $relPath
    $dir = Split-Path $fullPath -Parent
    if (-not (Test-Path $dir)) {
        New-Item -ItemType Directory -Force -Path $dir | Out-Null
    }
    $bytes = [System.Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($fullPath, $bytes)
    Write-Host "[OK] $relPath atualizado" -ForegroundColor Green
}

Write-Base64File "lib/appointments/google_calendar_provider.dart" ""
Write-Base64File "lib/ui/screens/auth_splash_screen.dart" ""
Write-Base64File "lib/main.dart" ""
Write-Base64File "lib/ui/screens/today_screen.dart" ""
Write-Base64File "lib/territory/geolocation_helper.dart" ""

$utf8NoBom = New-Object System.Text.UTF8Encoding($false)

# 1. Corrige zoom e coordenada padrao em lib/ui/widgets/map_location_picker_dialog.dart
$pickerPath = Join-Path $PWD "lib/ui/widgets/map_location_picker_dialog.dart"
if (Test-Path $pickerPath) {
    $pickerRaw = [System.IO.File]::ReadAllText($pickerPath, $utf8NoBom)
    # Substitui coordenadas de Manaus por Santo Antonio do Ica, AM (-3.1022, -67.9397)
    $pickerRaw = $pickerRaw.Replace("-3.1190", "-3.1022").Replace("-60.0217", "-67.9397")
    $pickerRaw = $pickerRaw.Replace("Manaus", "Santo Antonio do Ica")
    # Impede que o InteractiveViewer aplique escala simultanea ao scroll do mouse (causa do pulo de km no zoom)
    $pickerRaw = $pickerRaw.Replace("scaleEnabled: true,", "scaleEnabled: false,")
    if ($pickerRaw.Contains("_hasCenteredInitialView")) {
        $pickerRaw = $pickerRaw.Replace("_transformationController.value = Matrix4.identity();", "_hasCenteredInitialView = false;")
        # Garante que ao mudar _zoom, a camera mantenha o pino/endereco selecionado no centro da tela
        $pickerRaw = [regex]::Replace($pickerRaw, "(_zoom\s*=\s*\(_zoom\s*[\+\-]\s*1\)\.clamp\([^\)]+\);)", "`$1 _hasCenteredInitialView = false;")
    }
    [System.IO.File]::WriteAllText($pickerPath, $pickerRaw, $utf8NoBom)
    Write-Host "[OK] lib/ui/widgets/map_location_picker_dialog.dart atualizado (Zoom focado + Santo Antonio do Ica)" -ForegroundColor Green
}

# 2. Corrige zoom e coordenada padrao em lib/ui/screens/contacts_map_screen.dart
$contactsMapPath = Join-Path $PWD "lib/ui/screens/contacts_map_screen.dart"
if (Test-Path $contactsMapPath) {
    $mapRaw = [System.IO.File]::ReadAllText($contactsMapPath, $utf8NoBom)
    # Substitui coordenadas de Manaus por Santo Antonio do Ica, AM (-3.1022, -67.9397)
    $mapRaw = $mapRaw.Replace("-3.1190", "-3.1022").Replace("-60.0217", "-67.9397")
    # Inicializa o centro do mapa em Santo Antonio do Ica, AM (evita media entre cidades distantes)
    $mapRaw = $mapRaw.Replace("double? _viewportCenterLat;", "double? _viewportCenterLat = -3.1022;")
    $mapRaw = $mapRaw.Replace("double? _viewportCenterLng;", "double? _viewportCenterLng = -67.9397;")
    # Impede que o InteractiveViewer aplique escala na matriz durante o scroll do mouse
    $mapRaw = $mapRaw.Replace("scaleEnabled: true,", "scaleEnabled: false,")
    # Mantem a camera centralizada no ponto atual ao dar zoom ou centralizar
    $mapRaw = $mapRaw.Replace("_transformationController.value = Matrix4.identity();", "_hasCenteredInitialView = false;")
    $mapRaw = [regex]::Replace($mapRaw, "(_zoom\s*=\s*\(_zoom\s*[\+\-]\s*1\)\.clamp\([^\)]+\);)", "if (_selectedPinPerson?.latitude != null && _selectedPinPerson?.longitude != null) { _viewportCenterLat = _selectedPinPerson!.latitude; _viewportCenterLng = _selectedPinPerson!.longitude; } else if (_selectedPinLandmark != null) { _viewportCenterLat = _selectedPinLandmark!.latitude; _viewportCenterLng = _selectedPinLandmark!.longitude; } `$1 _hasCenteredInitialView = false;")
    [System.IO.File]::WriteAllText($contactsMapPath, $mapRaw, $utf8NoBom)
    Write-Host "[OK] lib/ui/screens/contacts_map_screen.dart atualizado (Zoom focado + Santo Antonio do Ica)" -ForegroundColor Green
}

# 3. Atualiza lib/territory/geocoding_service.dart e lib/core/demo_data.dart para Santo Antonio do Ica, AM
foreach ($relFile in @("lib/territory/geocoding_service.dart", "lib/core/demo_data.dart")) {
    $fPath = Join-Path $PWD $relFile
    if (Test-Path $fPath) {
        $fRaw = [System.IO.File]::ReadAllText($fPath, $utf8NoBom)
        $fRaw = $fRaw.Replace("-3.1190", "-3.1022").Replace("-60.0217", "-67.9397")
        $fRaw = $fRaw.Replace("Manaus, AM", "Santo Antonio do Ica, AM").Replace("Manaus, Amazonas", "Santo Antonio do Ica, Amazonas")
        [System.IO.File]::WriteAllText($fPath, $fRaw, $utf8NoBom)
        Write-Host "[OK] $relFile atualizado (Santo Antonio do Ica AM)" -ForegroundColor Green
    }
}

# 4. Adiciona limite LRU de 500 tiles em memoria na Web (lib/territory/tile_cache/tile_cache_web.dart)
$tileWebPath = Join-Path $PWD "lib/territory/tile_cache/tile_cache_web.dart"
if (Test-Path $tileWebPath) {
    $tileRaw = [System.IO.File]::ReadAllText($tileWebPath, $utf8NoBom)
    if (-not $tileRaw.Contains("_cache.length >= 500")) {
        $tileRaw = $tileRaw.Replace("_cache[key] = bytes;", "if (_cache.length >= 500) { _cache.remove(_cache.keys.first); }`n          _cache[key] = bytes;")
        [System.IO.File]::WriteAllText($tileWebPath, $tileRaw, $utf8NoBom)
        Write-Host "[OK] lib/territory/tile_cache/tile_cache_web.dart atualizado (LRU 500 tiles)" -ForegroundColor Green
    }
}

# 5. Atualiza owner_id automatico em lib/sync/supabase_sync_service.dart
$syncSvcPath = Join-Path $PWD "lib/sync/supabase_sync_service.dart"
if (Test-Path $syncSvcPath) {
    $syncRaw = [System.IO.File]::ReadAllText($syncSvcPath, $utf8NoBom)
    if (-not $syncRaw.Contains("remotePayload['owner_id']")) {
        $oldLine = "final remotePayload = toRemotePayload(op.entityType, cleanPayload);"
        $newLines = "final remotePayload = toRemotePayload(op.entityType, cleanPayload);`n          final currentUserId = client.auth.currentUser?.id;`n          if (currentUserId != null && currentUserId.isNotEmpty) {`n            remotePayload['owner_id'] = currentUserId;`n          }"
        $syncRaw = $syncRaw.Replace($oldLine, $newLines)
        [System.IO.File]::WriteAllText($syncSvcPath, $syncRaw, $utf8NoBom)
        Write-Host "[OK] lib/sync/supabase_sync_service.dart atualizado" -ForegroundColor Green
    }
}

Write-Host "Formatando arquivos Dart..." -ForegroundColor Cyan
dart format lib/main.dart lib/appointments/google_calendar_provider.dart lib/ui/screens/auth_splash_screen.dart lib/ui/screens/today_screen.dart lib/territory/geolocation_helper.dart lib/ui/widgets/map_location_picker_dialog.dart lib/ui/screens/contacts_map_screen.dart lib/sync/supabase_sync_service.dart

